using System;using System.IO;using System.Linq;using System.Reflection;using System.Threading;using System.Diagnostics;using System.Windows.Forms;using System.Web.Script.Serialization;using Microsoft.Web.WebView2.WinForms;
class AnPingDirectoryProbe{
 static string root=Directory.GetCurrentDirectory(),dir=Environment.GetEnvironmentVariable("CANIDELETE_CHECK_DIR");static JavaScriptSerializer js=new JavaScriptSerializer();static Stopwatch sw=Stopwatch.StartNew();static void Pump(int n){var end=DateTime.UtcNow.AddMilliseconds(n);while(DateTime.UtcNow<end){if(sw.Elapsed.TotalSeconds>60)throw new Exception("60s limit");Application.DoEvents();Thread.Sleep(3);}}
 static string Eval(WebView2 w,string s){var t=w.CoreWebView2.ExecuteScriptAsync(s);while(!t.IsCompleted)Pump(3);return t.Result;}static void Wait(WebView2 w,string s){var end=DateTime.UtcNow.AddSeconds(6);while(DateTime.UtcNow<end){if(Eval(w,s)=="true")return;Pump(15);}throw new Exception("wait "+s+" | "+Eval(w,"({state:S.state,dir:directoryState})"));}static void Check(WebView2 w,string n,string code){if(Eval(w,code)!="true")throw new Exception(n);Console.WriteLine("PASS "+n);}static void Shot(WebView2 w,string n){Pump(400);using(var f=File.Create(Path.Combine(dir,n+".png"))){var t=w.CoreWebView2.CapturePreviewAsync(Microsoft.Web.WebView2.Core.CoreWebView2CapturePreviewImageFormat.Png,f);while(!t.IsCompleted)Pump(3);}}
 [STAThread]static int Main(){try{if(string.IsNullOrWhiteSpace(dir))throw new InvalidOperationException("CANIDELETE_CHECK_DIR must be set.");dir=Path.GetFullPath(dir);Directory.CreateDirectory(dir);Environment.SetEnvironmentVariable("WEBVIEW2_USER_DATA_FOLDER",Path.Combine(dir,"profile"));AppDomain.CurrentDomain.AssemblyResolve+=(s,e)=>{string n=new AssemblyName(e.Name).Name,p=n=="can-i-delete"?Path.Combine(root,"can-i-delete.exe"):Path.Combine(root,"lib",n+".dll");return File.Exists(p)?Assembly.LoadFrom(p):null;};return Run();}catch(Exception e){Console.WriteLine(e);return 1;}}
 static int Run(){Application.EnableVisualStyles();string fx=Path.Combine(Environment.GetEnvironmentVariable("ANPING_FIXTURE_ROOT")??dir,"fixture");Directory.CreateDirectory(fx);for(int i=0;i<105;i++){string d=Path.Combine(fx,"项目-"+i);Directory.CreateDirectory(d);File.WriteAllText(Path.Combine(d,"file.txt"),new string('x',i+1));}string deep=Path.Combine(fx,"大型资料","二层","三层");Directory.CreateDirectory(deep);File.WriteAllText(Path.Combine(deep,"很长的文件名称-"+new string('字',60)+".txt"),new string('x',1000));File.WriteAllText(Path.Combine(fx,"根文件.txt"),"root");
 using(var f=new AnPingForm()){f.Show();var w=f.Controls.OfType<WebView2>().Single();while(w.CoreWebView2==null)Pump(10);Wait(w,"document.readyState==='complete'&&typeof S==='object'&&typeof directoryState==='object'");Eval(w,"window.chrome.webview.postMessage(JSON.stringify({action:'startScan',targets:["+js.Serialize(fx)+"]}));");Wait(w,"S.state==='done'");Eval(w,"if(legend.classList.contains('show'))$('legendOk').click();$('viewDirectories').click();");Wait(w,"directoryState.page&&!directoryState.loading");Check(w,"root totals file-derived and bounded","directoryState.page.totalFileCount===107&&directoryState.page.totalBytes===6569&&directoryState.page.rows.length===100&&!directoryState.page.partial");Shot(w,"01-目录首页");
 Eval(w,"$('directoryNext').click()");Wait(w,"!directoryState.loading&&directoryState.page.pageOffset===100");Check(w,"last page reachable","directoryState.page.rows.length===7");Eval(w,"$('directoryPrev').click()");Wait(w,"!directoryState.loading&&directoryState.page.pageOffset===0");
 for(int i=0;i<3;i++){Eval(w,"$('directoryRows').querySelector('[data-row]').click()");Wait(w,"!directoryState.loading");}Check(w,"three levels breadcrumb and file id","directoryState.page.breadcrumb.length===4&&directoryState.page.rows[0].file.id>0");Shot(w,"02-子目录");Eval(w,"$('directoryRows').querySelector('[data-row]').click()");Wait(w,"drawerOpen&&!!dState.detailKey");Check(w,"same file details and readonly actions","drawer.textContent.includes('很长的文件名称')&&drawer.textContent.includes('复制路径')&&!drawer.querySelector('[data-a=delete]')");Eval(w,"$('detailBack').click()");Wait(w,"!drawerOpen");Check(w,"returns to same directory","directoryState.page.breadcrumb.length===4");Eval(w,"$('directoryUp').click();$('directoryCrumbs').querySelector('[data-dir=\"0\"]').click()");Wait(w,"!directoryState.loading&&directoryState.page.directoryId===0");
 Eval(w,"let before=directoryState.page;receiveDirectory({action:'directoriesPage',request:directoryState.request-1,scanSessionId:currentScanSession,rows:[]});window.__same=before===directoryState.page;");Check(w,"late reply ignored","window.__same");Check(w,"no directory deletion entry","!$('directoryPanel').querySelector('[data-a=delete],#cGo')");
 f.ClientSize=new System.Drawing.Size(760,520);Pump(300);Eval(w,"nativeTextScale=2;fit();");Check(w,"large text directory footer stays reachable","(()=>{let r=$('directoryNext').getBoundingClientRect();return r.bottom<=innerHeight&&r.top>=0&&$('directoryRows').clientHeight>20;})()");
 Eval(w,"directoryState.loading=true;window.chrome.webview.postMessage(JSON.stringify({action:'startScan',targets:["+js.Serialize(fx)+"]}));");Wait(w,"S.state==='done'&&directoryState.page&&!directoryState.loading");Check(w,"new scan clears pending navigation and old ids","directoryState.page.scanSessionId===currentScanSession&&directoryState.page.directoryId===0");f.Close();}Console.WriteLine("RESULT OK directory native checks");return 0;}
}
